#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  } Queue_CheckBox;void SendDataHS(Queue_CheckBox* p, SQueue& q){		CShHS* sh = (CShHS*)PipeSh;		if ( IsTypeOk )		{		  SSendToModel send;		  lstrcpy( send.szValue, "MV" );// Имя переменной		  bool Old = sh->mOn;		  bool New = !sh->mOn;		  send.Set( enumValueBol, &Old, &New );		  q.m_pPipe->SendData( p->nNumber, send );		}}int PressCheckBox(DefinePress){  Queue_CheckBox* p = (Queue_CheckBox*)s;  if ( nCode == 2 )		SendDataHS(p,q);  return 0;}// Функция отображенияint PaintCheckBox(DefinePaint)  {  QueueP(Queue_CheckBox);  //  int nNumber=-1;  RECT rc = p->mRect;  CShHS* sh = (CShHS*)PipeSh;	if ( IsTypeOk )	{        if ( sh->mOn )            nNumber = 1;        else            nNumber = 0;	}  if (nNumber==-1)  {     if ( ::GetMnemoStyle() & MNEMO_EDIT )     {       COLORREF clr=0x80ff;       CMyPen pen( hDC, clr );			 pen.Rect( rc );     }  }  else  {    if (nNumber==1)    {       CMyPen pen(hDC, 0,2);       int nX0=p->mRect.left+2;       int nY0=p->mRect.top+2;       int nX1=nX0+4;       int nY1=nY0+6;       int nX2=nX1+4;       int nY2=nY1-6;       ::MoveToEx( hDC, nX0, nY0, NULL );       ::LineTo  ( hDC, nX1, nY1 );       ::LineTo  ( hDC, nX2, nY2 );    }  }  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddCheckBox(DefineTegs)  {  //  AddQueueEx(Queue_CheckBox);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintCheckBox;  p->press = &PressCheckBox;  //  //  p->nNumber=-1;  char szHsName[64]="";  //  STegObj obj[] =    {	  { 'S', "hsName", szHsName, 63 },    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  if (*szHsName)	  p->nNumber=def.AddKind( id_HS    , szHsName );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~